  constructor(C _c) { c = _c; }
  function test(uint256 supply, uint256 v) public {
    require(supply > 0 && v > 0 && v <= supply);
    c.burn(v);
    assert(c.totalSupply() == supply - v);
  }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 v) public {
    uint256 before = c.totalSupply();
    c.burn(v);
    assert(c.totalSupply() == before - v);
  }
}

contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function burnMustRevertForNonOwner(uint256 v) public {
    require(msg.sender != c.owner(), "caller must not be owner");
    require(v == 0, "value must be zero so only the access check decides");
    bool ok = true;
    try c.burn(v) {
      ok = true;
    } catch {
      ok = false;
    }
    assert(!ok);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function testNonOwnerBurnReverts() public {
    // The test contract is not the owner of c, so any burn attempt from it
    // must revert under the correct owner check.
    bool ok;
    (ok, ) = address(c).call(abi.encodeWithSelector(C.burn.selector, uint256(0)));
    assert(!ok);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 v) public {
    require(c.owner() == address(this));
    require(c.balanceOf(address(this)) >= v);
    uint256 before = c.balanceOf(address(this));
    c.burn(v);
    assert(c.balanceOf(address(this)) < before);
  }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function testBurn(uint256 v) public {
        require(v > 0);
        require(c.balanceOf(msg.sender) >= v);
        c.burn(v);
        assert(c.balanceOf(msg.sender) == c.balanceOf(msg.sender) + v - v);
    }
}

contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function test(address t, uint256 amt) public {
    require(amt > 0);
    uint256 before = c.balanceOf(address(this));
    require(before >= amt);
    c.transfer(t, amt);
    assert(c.balanceOf(address(this)) == before - amt);
  }
}

contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function test(address to, uint256 v) public {
    uint256 before = c.balanceOf(to);
    c.transfer(to, v);
    assert(c.balanceOf(to) == before + v);
  }
}
